using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Threading;
using System.Xml;
namespace ExperimentMonitor {
 public sealed class StorageTestHarness:MarshalByRefObject {public int Execute(){return StorageTests.Run();}}
 public static class StorageTests {
  static void Check(bool ok,string name){if(!ok)throw new Exception("存储测试失败："+name);}
 public static int Run(){string root=Path.Combine(Path.GetTempPath(),"experiment-storage-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);int tests=0;try{DateTime utc=DateTime.UtcNow;var filter=new HistoryFilter{FromUtc=utc.AddDays(-90),ToUtc=utc.AddMinutes(1),Source="simulation"};using(var store=new ExperimentStore(root,"simulation","{config:test}")){store.Ready.GetAwaiter().GetResult();string id=store.BeginExperiment("test","=formula");for(int i=0;i<3;i++)store.Record(new Observation{Point="T0",Description="=unsafe",Device="PLC",Source="simulation",Status=i==2?"超时":"正常",Quality=i==2?"timeout":"good",Value=i==2?"等待超时":"-1.25",Number=i==2?(double?)null:-1.25,RawNumber=i==2?(double?)null:-1.25,Unit="℃",ConfigVersion="sha256-test",Utc=utc.AddDays(i==0?-60:0),Tx=new byte[]{1,3},Rx=new byte[0],Payload=new byte[0]},i,"℃");store.EndExperiment();store.FlushAsync().GetAwaiter().GetResult();Check(store.Committed==3,"flush提交全部队列");tests++;filter.ExperimentId=id;Check(ExperimentHistory.Count(root,filter)==3,"跨分期实验过滤");tests++;}Check(ExperimentHistory.Databases(root,"simulation").Count()==2,"30天跨库");tests++;Check(ExperimentHistory.Count(root,new HistoryFilter{FromUtc=filter.FromUtc,ToUtc=filter.ToUtc,Source="serial"})==0,"模拟实机隔离");tests++;var fullPage=ExperimentHistory.Query(root,filter);var page1=ExperimentHistory.QueryPage(root,filter,0,2);var page2=ExperimentHistory.QueryPage(root,filter,2,2);Check(page1.Count==2&&page2.Count==1&&page1.Concat(page2).Select(x=>x.Database+"|"+x.Id).SequenceEqual(fullPage.Select(x=>x.Database+"|"+x.Id)),"跨分期分页无重漏");tests++;var experiments=ExperimentHistory.ListExperiments(root,"simulation");Check(experiments.Count==1&&experiments[0].Name=="test"&&experiments[0].EndedUtc.HasValue,"跨分期实验目录及结束时间");tests++;var rows=ExperimentHistory.Query(root,filter);Check(rows.Count==3&&rows.Count(x=>x.Number==null)==1&&rows.Any(x=>x.Number==-1.25),"负数及失败空值保留");tests++;Check(rows.All(x=>x.ConfigVersion=="sha256-test")&&rows.Any(x=>x.Quality=="timeout"),"质量和配置版本");tests++;filter.Points=new[]{"missing"};Check(ExperimentHistory.Count(root,filter)==0,"测点过滤");tests++;filter.Points=new string[0];var xlsx=ExperimentExport.ExportAsync(root,filter,root,"xlsx",null,CancellationToken.None).GetAwaiter().GetResult();Check(xlsx.Rows==3&&xlsx.Files.Length==1,"Excel单工作簿完整导出");tests++;using(var z=ZipFile.OpenRead(Path.Combine(xlsx.OutputDirectory,xlsx.Files[0]))){var nsDoc=new XmlDocument();using(var stream=z.GetEntry("xl/workbook.xml").Open())nsDoc.Load(stream);var ns=new XmlNamespaceManager(nsDoc.NameTable);ns.AddNamespace("s","http://schemas.openxmlformats.org/spreadsheetml/2006/main");Check(nsDoc.SelectNodes("//s:sheet",ns).Count==4,"四个语义工作表");tests++;var wide=new XmlDocument();using(var stream=z.GetEntry("xl/worksheets/sheet1.xml").Open())wide.Load(stream);Check(wide.SelectNodes("//s:sheetData/s:row",ns).Count==4&&wide.OuterXml.Contains("-1.25"),"宽表逐轮且负数为数值");tests++;var detail=new XmlDocument();using(var stream=z.GetEntry("xl/worksheets/sheet2.xml").Open())detail.Load(stream);Check(detail.SelectNodes("//s:sheetData/s:row",ns).Count==4&&detail.OuterXml.Contains("timeout"),"明细包含全部记录质量");tests++;var quality=new XmlDocument();using(var stream=z.GetEntry("xl/worksheets/sheet3.xml").Open())quality.Load(stream);Check(quality.SelectNodes("//s:sheetData/s:row",ns).Count==4&&quality.OuterXml.Contains("timeout")&&quality.OuterXml.Contains("超时"),"质量表包含枚举值和状态说明");tests++;var info=new XmlDocument();using(var stream=z.GetEntry("xl/worksheets/sheet4.xml").Open())info.Load(stream);Check(info.SelectNodes("//s:sheetData/s:row",ns).Count>8&&info.OuterXml.Contains("记录条数"),"说明表包含可审阅的筛选和导出元数据");tests++;}var csv=ExperimentExport.ExportAsync(root,filter,root,"csv",null,CancellationToken.None).GetAwaiter().GetResult();string wideCsv=File.ReadAllText(Path.Combine(csv.OutputDirectory,csv.Files.First(f=>f.Contains("宽表"))));string detailCsv=File.ReadAllText(Path.Combine(csv.OutputDirectory,csv.Files.First(f=>f.Contains("明细"))));string qualityCsv=File.ReadAllText(Path.Combine(csv.OutputDirectory,csv.Files.First(f=>f.Contains("质量"))));Check(csv.Rows==3&&csv.Files.Count(f=>f.EndsWith(".csv"))==3,"CSV生成宽表、明细和质量三套文件");tests++;Check(wideCsv.Split(new[]{'\n'},StringSplitOptions.RemoveEmptyEntries).Length==4&&wideCsv.Contains("-1.25"),"CSV宽表输出全部真实轮次和值");tests++;Check(detailCsv.Split(new[]{'\n'},StringSplitOptions.RemoveEmptyEntries).Length==4&&!detailCsv.Contains("=unsafe")&&detailCsv.Contains(PointCatalog.Get("T0").Label),"CSV明细用当前名称映射且旧描述不外泄");tests++;Check(qualityCsv.Split(new[]{'\n'},StringSplitOptions.RemoveEmptyEntries).Length==4&&qualityCsv.Contains("timeout"),"CSV质量文件真实记录");tests++;var next=ExperimentExport.ExportAsync(root,filter,root,"xlsx",null,CancellationToken.None).GetAwaiter().GetResult();Check(next.OutputDirectory!=xlsx.OutputDirectory&&File.Exists(Path.Combine(xlsx.OutputDirectory,xlsx.Files[0])),"不覆盖先前导出");tests++;ExperimentExport.RowsPerVolume=2;try{var split=ExperimentExport.ExportAsync(root,filter,root,"xlsx",null,CancellationToken.None).GetAwaiter().GetResult();Check(split.Files.Length==2&&split.Rows==3,"分卷不拆轮次（文件数="+split.Files.Length+"，记录="+split.Rows+"）");tests++;}finally{ExperimentExport.RowsPerVolume=100000;}var cancel=new CancellationTokenSource();cancel.Cancel();try{ExperimentExport.ExportAsync(root,filter,root,"xlsx",null,cancel.Token).GetAwaiter().GetResult();throw new Exception("应取消");}catch(OperationCanceledException){tests++;}Check(Directory.GetDirectories(root,".experiment-export-*",SearchOption.AllDirectories).Length==0,"取消无半成品发布");tests++;using(var budgetStore=new ExperimentStore(Path.Combine(root,"budget"),"simulation","")){budgetStore.Ready.GetAwaiter().GetResult();try{budgetStore.Record(new Observation{Source="simulation",Value=new string('x',9*1024*1024),Utc=utc},1,"");throw new Exception("预算应拒绝");}catch(IOException){Check(budgetStore.LastError.Length>0&&!budgetStore.Status.Recording,"16MiB预算超限显式停止");tests++;}}return tests;}finally{ExperimentExport.RowsPerVolume=100000;Directory.Delete(root,true);}}
 }
}

